/* Lock a nonzero global memory handle, returning null for zero. */
extern void far * far pascal GlobalLock(unsigned);
void far * MaLock(unsigned handle)
{
    if (handle)
        return GlobalLock(handle);
    return 0L;
}

/* Copy a counted byte range while carrying through huge-pointer arithmetic. */
void MaMemCpy(unsigned char huge *destination, const unsigned char huge *source, unsigned long length)
{
    while (length != 0) {
        *destination++ = *source++;
        --length;
    }
}

/* Copy each byte explicitly; the backward path begins at the final byte of
   the same far ranges. */
void far MaMemMove(unsigned char far *destination,
                   unsigned char far *source,
                   unsigned long length)
{
    if (destination < source) {
        while (length != 0UL) {
            *destination = *source;
            ++destination;
            ++source;
            --length;
        }
    } else {
        destination += length - 1UL;
        source += length - 1UL;
        while (length != 0UL) {
            *destination = *source;
            --destination;
            --source;
            --length;
        }
    }
}

