/* Zero an NCB, submit it, and report the missing NetBIOS responder. */
extern void far NetBios(unsigned char far *);
extern int far DebugWinPrintf(char far *, ...);
int NbCheck(void)
{
    unsigned char ncb[64];
    unsigned i;
    for (i = 0; i < 64; ++i)
        ncb[i] = 0;
    ncb[0] = 0x7f;
    NetBios((unsigned char far *)ncb);
    if (ncb[0x31] != 3) {
        DebugWinPrintf("NetBIOS not loaded (No response from Int5C).\n");
        return 0;
    }
    return 1;
}

/* Build a NetBIOS Call NCB with space-padded calling names. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];

void far NbCall(char far *local_name, char far *remote_name,
                unsigned char session, unsigned char number)
{
    unsigned char ncb[64] = { 0 };
    int length;
    int i;

    ncb[0] = 0x10;
    for (i = 0; i < 16; ++i)
        ncb[0x0a + i] = 0x20;
    length = 0;
    while (remote_name[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        ncb[0x0a + i] = remote_name[i];
    ncb[0x19] = 0;

    for (i = 0; i < 16; ++i)
        ncb[0x1a + i] = 0x20;
    length = 0;
    while (local_name[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        ncb[0x1a + i] = local_name[i];
    ncb[0x29] = 0;

    ncb[0x0e] = session;
    ncb[0x10] = number;
    NetBios(ncb);
    DebugWinPrintf("NetBIOS call");
    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS call status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS call status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS call status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
}

/* Put the requested name into a space-padded Add Name command block, submit
   it, then return the name number assigned by NetBIOS. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];

unsigned char far NbAddName(char far *name)
{
    unsigned char ncb[64] = { 0 };
    int length;
    int i;

    ncb[0] = 0x30;
    for (i = 0; i < 16; ++i)
        ncb[0x1a + i] = 0x20;

    length = 0;
    while (name[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        ncb[0x1a + i] = name[i];
    ncb[0x29] = 0;

    NetBios(ncb);
    DebugWinPrintf("NetBIOS add name");

    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS add-name status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS add-name status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS add-name status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);

    return ncb[3];
}

/* NetBios Reset with a byte-addressed automatic 64-byte control block. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];
unsigned int far NbReset(void)
{
    unsigned char ncb[64];
    int i;
    for (i = 0; i < 64; ++i)
        ncb[i] = 0;
    ncb[0] = 0x32;
    NetBios(ncb);
    DebugWinPrintf("NetBIOS reset");
    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS reset status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS reset status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS reset status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
}

/* Send with a byte-addressed local NCB and its original far buffer. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];
void far NbSend(unsigned char far *buffer, unsigned int length,
                unsigned char session)
{
    unsigned char ncb[64];
    int i;
    for (i = 0; i < 64; ++i)
        ncb[i] = 0;
    ncb[0] = 0x14;
    ncb[2] = session;
    *(unsigned char far **)&ncb[4] = buffer;
    *(unsigned int far *)&ncb[8] = length;
    NetBios(ncb);
    DebugWinPrintf("NetBIOS send");
    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS send status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS send status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS send status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
}

/* Build a NetBIOS Listen NCB from the local and remote names. */
extern unsigned int far strlen(char far *s);
extern void far *far memcpy(void far *d, void far *s, unsigned int n);
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];

void far NbListen(char far *remote_name, char far *local_name,
                  unsigned char session, unsigned char number)
{
    unsigned char ncb[64] = { 0 };
    unsigned int length;

    ncb[0] = 0x11;
    memset(ncb + 0x0a, 0x20, 16);
    length = strlen(remote_name);
    if (length > 16)
        length = 16;
    memcpy(ncb + 0x0a, remote_name, length);
    ncb[0x19] = 0;

    memset(ncb + 0x1a, 0x20, 16);
    length = strlen(local_name);
    if (length > 16)
        length = 16;
    memcpy(ncb + 0x1a, local_name, length);
    ncb[0x29] = 0;

    ncb[0x0e] = session;
    ncb[0x10] = number;
    NetBios(ncb);
    DebugWinPrintf("NetBIOS listen");

    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS listen status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS listen status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS listen status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
}

/* Set up the shared NCB for an asynchronous listen. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern unsigned char near edata[];
extern char near left_wedge[];
extern unsigned char far Dx8[];

void far NbPostListen(char far *name, char far *call_name,
                      unsigned char session, unsigned char number,
                      void far *buffer)
{
    int i;
    int length;
    unsigned int status;

    for (i = 0; i < 64; ++i)
        edata[0x112 + i] = 0;
    edata[0x112] = 0x91;

    for (i = 0; i < 16; ++i)
        edata[0x11c + i] = 0x20;
    length = 0;
    while (call_name[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        edata[0x11c + i] = call_name[i];
    edata[0x12b] = 0;

    for (i = 0; i < 16; ++i)
        edata[0x12c + i] = 0x20;
    length = 0;
    while (name[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        edata[0x12c + i] = name[i];
    edata[0x13b] = 0;

    edata[0x13c] = session;
    edata[0x13d] = number;
    *(void far * far *)(edata + 0x13e) = buffer;
    NetBios((void far *)(edata + 0x112));
    DebugWinPrintf((char far *)(left_wedge + 0x26e),
                   (char far *)(edata + 0x11c));

    status = edata[0x113];
    if (status < 0x50)
        DebugWinPrintf((char far *)(left_wedge + 0x1b4), status,
                       Dx8 + 0xa7f0 + status * 60);
    else if (status < 0xf0)
        DebugWinPrintf((char far *)(left_wedge + 0x1ce), status);
    else
        DebugWinPrintf((char far *)(left_wedge + 0x1fa), status,
                       Dx8 + 0x8270 + status * 60);
}

/* Put the requested name into a space-padded Delete Name command block, submit
   it, then return the name number assigned by NetBIOS. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];

void far NbDeleteName(char far *name)
{
    unsigned char ncb[64] = { 0 };
    int length;
    int i;

    ncb[0] = 0x31;
    for (i = 0; i < 16; ++i)
        ncb[0x1a + i] = 0x20;

    length = 0;
    while (name[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        ncb[0x1a + i] = name[i];
    ncb[0x29] = 0;

    NetBios(ncb);
    DebugWinPrintf("NetBIOS delete name");

    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS delete-name status %u: %s", ncb[0x31],
