    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS delete-name status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS delete-name status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);

}

/* Submit a Receive command with the caller's buffer and current length, then
   copy the length returned in the command block back to the caller. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];

struct NetbiosControlBlock {
    unsigned char command;
    unsigned char immediate_status;
    unsigned char session;
    unsigned char reserved0;
    unsigned char far *buffer;
    unsigned int length;
    unsigned char reserved[0x27];
    unsigned char final_status;
    unsigned char tail[14];
};

unsigned int far NbReceive(unsigned char session,
                           unsigned char far *buffer,
                           unsigned int far *length)
{
    struct NetbiosControlBlock ncb;
    unsigned char near *p;

    for (p = (unsigned char near *)&ncb; p < (unsigned char near *)&ncb + 64; ++p)
        *p = 0;
    ncb.command = 0x15;
    ncb.session = session;
    ncb.buffer = buffer;
    ncb.length = *length;
    NetBios(&ncb);
    DebugWinPrintf("NetBIOS receive");

    if (ncb.final_status < 0x50)
        DebugWinPrintf("NetBIOS receive status %u: %s", ncb.final_status,
                       (char far *)NB_RETCODE[ncb.final_status]);
    else if (ncb.final_status < 0xf0)
        DebugWinPrintf("NetBIOS receive status %u", ncb.final_status);
    else
        DebugWinPrintf("NetBIOS receive status %u: %s", ncb.final_status,
                       (char far *)NB_RETCODE[ncb.final_status]);

    *length = ncb.length;
    return ncb.final_status;
}

/* Reuse the shared 64-byte NetBIOS control block for Post Receive Any, passing
   the caller's buffer, capacity and timeout through the corresponding fields. */
static unsigned char near postReceiveNcb[64];

extern void far NetBios(unsigned char far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];

unsigned int far NbPostReceiveAny(unsigned char session,
                                  unsigned char far *buffer,
                                  unsigned int length,
                                  unsigned long timeout)
{
    int i;

    for (i = 0; i < 64; ++i)
        postReceiveNcb[i] = 0;

    postReceiveNcb[0] = 0x96;
    postReceiveNcb[3] = session;
    *(unsigned char far **)&postReceiveNcb[4] = buffer;
    *(unsigned int far *)&postReceiveNcb[8] = length;
    *(unsigned long far *)&postReceiveNcb[0x2c] = timeout;
    NetBios(postReceiveNcb);
    DebugWinPrintf("NetBIOS post receive any");

    if (postReceiveNcb[1] < 0x50)
        DebugWinPrintf("NetBIOS post-receive status %u: %s", postReceiveNcb[1],
                       (char far *)NB_RETCODE[postReceiveNcb[1]]);
    else if (postReceiveNcb[1] < 0xf0)
        DebugWinPrintf("NetBIOS post-receive status %u", postReceiveNcb[1]);
    else
        DebugWinPrintf("NetBIOS post-receive status %u: %s", postReceiveNcb[1],
                       (char far *)NB_RETCODE[postReceiveNcb[1]]);

    return postReceiveNcb[1];
}

/* Hang Up with a byte-addressed local NCB and the session at byte two. */
extern void far NetBios(void far *ncb);
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];
void far NbHangUp(unsigned char session)
{
    unsigned char ncb[64];
    int i;
    for (i = 0; i < 64; ++i)
        ncb[i] = 0;
    ncb[0] = 0x12;
    ncb[2] = session;
    NetBios(ncb);
    DebugWinPrintf("NetBIOS hang up");
    if (ncb[0x31] < 0x50)
        DebugWinPrintf("NetBIOS hang up status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
    else if (ncb[0x31] < 0xf0)
        DebugWinPrintf("NetBIOS hang up status %u", ncb[0x31]);
    else
        DebugWinPrintf("NetBIOS hang up status %u: %s", ncb[0x31],
                       (char far *)NB_RETCODE[ncb[0x31]]);
}

/* Pad a 16-byte name with spaces, copy the source prefix, and terminate. */
void CopyName(char far *destination, const char far *source)
{
    unsigned i;
    unsigned length = 0;
    for (i = 0; i < 16; ++i)
        destination[i] = ' ';
    while (source[length] != 0)
        ++length;
    if (length > 16)
        length = 16;
    for (i = 0; i < length; ++i)
        destination[i] = source[i];
    destination[15] = 0;
}

/* Probe the far-qualified return-message pointer used by the status report. */
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];
struct NetbiosControlBlock {
    unsigned char command;
    unsigned char immediate_status;
    unsigned char reserved[0x2f];
    unsigned char final_status;
};

void far NbFinalStatus(struct NetbiosControlBlock far *ncb)
{
    union StatusSlot { unsigned short whole; unsigned char value; } statusSlot;

    statusSlot.value = ncb->final_status;
    if (statusSlot.value < 0x50)
        DebugWinPrintf("NetBIOS final status %u: %s", statusSlot.value,
                       (char far *)NB_RETCODE[statusSlot.value]);
    else if (ncb->final_status < 0xf0)
        DebugWinPrintf("NetBIOS final status %u", statusSlot.value);
    else
        DebugWinPrintf("NetBIOS final status %u: %s", statusSlot.value,
                       (char far *)NB_RETCODE[statusSlot.value - 0xa0]);
}

/* Report the immediate NetBIOS return byte and use the return-message table
   for status values outside the command-pending range. */
extern void far DebugWinPrintf(char far *format, ...);
extern char __based(__segname("SIMANT_DATA_GROUP")) NB_RETCODE[128][60];
struct NetbiosControlBlock {
    unsigned char command;
    unsigned char immediate_status;
    unsigned char reserved[0x2f];
    unsigned char final_status;
};

void far NbImmediateStatus(struct NetbiosControlBlock far *ncb)
{
    union StatusSlot { unsigned short whole; unsigned char value; } statusSlot;

    statusSlot.value = ncb->immediate_status;
    if (statusSlot.value < 0x50)
        DebugWinPrintf("NetBIOS RetCode(%#x): %s\n", statusSlot.value,
                       (char far *)NB_RETCODE[statusSlot.value]);
    else if (ncb->immediate_status < 0xf0)
        DebugWinPrintf("NetBIOS RetCode(%#x): Adapter malfunction.\n", statusSlot.value);
    else
        DebugWinPrintf("NetBIOS RetCode(%#x): %s\n", statusSlot.value,
                       (char far *)NB_RETCODE[statusSlot.value - 0xa0]);
}
